// 1. Ambil ID waktu unik yang berganti setiap 15 menit (900.000 milidetik)
const blockWaktu = Math.floor(Date.now() / 900000);

// 2. Rumus matematika LCG dengan salt rahasia agar menghasilkan 6 digit yang konsisten selama 15 menit
const seed = blockWaktu ^ 54321; 
const otpSistem = ((seed * 1103515245 + 12345) % 900000 + 100000).toString();

// 3. Tampilkan langsung ke web browser pengguna
return [{
    json: {
        status: "AUTHORIZED_GATEWAY",
        sistem: "SmartLedger Secure Session",
        otp_dinamis: otpSistem,
        catatan: "Kode ini akan tetap sama jika di-refresh dalam rentang 15 menit yang sama.",
        berlaku: "Maksimal 15 Menit"
    }
}];

// 1. Ambil data pesan asli dari Telegram Trigger
const dataTelegram = $("Telegram Trigger").all();

// 2. Hitung rumus OTP sistem untuk slot 15 menit SEKARANG
const blockSekarang = Math.floor(Date.now() / 900000);
const seedSekarang = blockSekarang ^ 54321;
const otpSahSistem = ((seedSekarang * 1103515245 + 12345) % 900000 + 100000).toString();

// 3. Injeksi OTP sah ini langsung ke variabel n8n (KODE 999999 SUDAH DIHAPUS TOTAL)
for (let item of dataTelegram) {
    item.json.otp_sah_sistem = otpSahSistem;
}

return dataTelegram;
